using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GainSandsOfTimePreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Sothis/GainSandsOfTimePreviewDescription", order = 0)]
public class GainSandsOfTimePreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as GainSandsOfTimeBasedAction).GetSandsOfTimeAmount(GetAmountWithoutEquation(amountModified));
	}
}
